(function(){'use strict';const $=s=>document.querySelector(s),S=Staff,M=Repayment,actor=KashierData.userId(),owner=(new URLSearchParams(location.search).get('owner')||'').toLowerCase(),key='kashier.staff.repayment.v1.'+actor+'.'+owner;let current=null,pending=null,blocked=false,busy=false,life=0,searchRequest=0,balanceRequest=0,receiptRequest=0,offset=0,hasPrevious=false,hasNext=false,selectedReceipt=null;
const active=()=>actor&&KashierData.loggedIn()&&KashierData.userId()===actor,node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=String(text);return e;},status=t=>$('#repay-status').textContent=t;
function controls(){const locked=busy||Boolean(pending)||blocked||!active();for(const id of ['query','search','previous','next','customer','refresh','new'])$('#repay-'+id).disabled=locked;$('#repay-previous').disabled=locked||!hasPrevious;$('#repay-next').disabled=locked||!hasNext;for(const id of ['amount','note','post'])$('#repay-'+id).disabled=locked||!current;$('#repay-retry').hidden=!pending;$('#repay-retry').disabled=busy||!active();$('#repay-print').disabled=busy||!selectedReceipt||!active();}
function clearBalance(){balanceRequest++;current=null;$('#repay-balance').textContent='';$('#repay-balance').hidden=true;controls();}
function clearReceipt(){receiptRequest++;selectedReceipt=null;$('#repay-receipt').replaceChildren();$('#repay-receipt').hidden=true;controls();}
function clearPrivate(){life++;searchRequest++;clearBalance();clearReceipt();$('#repay-customers').replaceChildren();$('#repay-recent').replaceChildren();$('#repay-page').textContent='';hasPrevious=hasNext=false;for(const id of ['query','amount','note','customer'])$('#repay-'+id).value='';controls();}
function removePending(){try{sessionStorage.removeItem(key);}catch{blocked=true;}pending=null;}
function denied(e){if(['staff_access_denied','staff_auth_required'].includes(e.saleCode)){clearPrivate();return true;}return false;}
async function recent(){const epoch=life;try{const v=await KashierData.listCashierRepayments(owner);if(epoch!==life||!active())return;M.recent(v,owner,actor);$('#repay-recent').replaceChildren();for(const e of v.rows){const b=node('button','D-'+e.movement_no+' · '+e.customer_name+' · '+S.format(e.amount)+' دینار');b.addEventListener('click',()=>show(e.id));$('#repay-recent').append(b);}}catch(e){if(epoch===life){$('#repay-recent').replaceChildren();denied(e);}}}
async function search(){if(busy||pending||blocked)return;clearBalance();$('#repay-customers').replaceChildren();$('#repay-customer').value='';const q=$('#repay-query').value.trim();if(!active()){clearPrivate();location.replace('auth.html?next='+encodeURIComponent('repayment.html?owner='+owner));return;}if(!S.uuid(owner)||q.length>100){status('ناسنامەی دوکان یان وشەی گەڕان نادروستە.');return;}const mine=++searchRequest,epoch=life,at=offset;status('گەڕان بۆ کڕیار…');try{const v=await KashierData.getCashierCustomers(owner,q,at);if(mine!==searchRequest||epoch!==life||!active())return;S.customers(v,owner,actor,q,at);for(const c of v.rows){const b=node('button',c.name+' · '+(c.phone||'بەبێ مۆبایل')+' · '+c.id);b.type='button';b.addEventListener('click',()=>select(c.id));$('#repay-customers').append(b);}$('#repay-page').textContent=(at+1)+' · '+v.total;hasPrevious=at>0;hasNext=BigInt(at+v.rows.length)<BigInt(v.total);controls();status(v.rows.length?'کڕیارێک هەڵبژێرە بۆ پشکنینی قەرزی ئێستا.':'هیچ کڕیارێک نەدۆزرایەوە.');await recent();}catch(e){if(mine===searchRequest&&epoch===life){denied(e);status((globalThis.KashierLocale?.message(e.message)??e.message));}}}
async function select(id){if(busy||pending||blocked||!active())return;clearBalance();$('#repay-customer').value=id;const mine=++balanceRequest,epoch=life;status('پشکنینی قەرزی کڕیار…');try{const v=await KashierData.getCashierCustomerBalance(owner,id);if(mine!==balanceRequest||epoch!==life||!active())return;current=M.balance(v,owner,actor,id);$('#repay-balance').textContent=v.customer.name+' · '+(v.customer.phone||'بەبێ مۆبایل')+' · قەرزی ئێستا: '+S.format(v.balance)+' دینار';$('#repay-balance').hidden=false;status('بڕ و هۆکاری وەرگرتنەوە بنووسە.');}catch(e){if(mine===balanceRequest&&epoch===life){denied(e);status((globalThis.KashierLocale?.message(e.message)??e.message));}}finally{controls();}}
function render(s){selectedReceipt=s;const e=s.entry,p=$('#repay-receipt');p.replaceChildren(node('h2',s.store_name+' · D-'+e.movement_no),node('p','کڕیار: '+e.customer_name),node('p','وەرگر: '+e.actor_name),node('p',new Intl.DateTimeFormat('ckb-IQ-u-ca-gregory-nu-latn',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'medium'}).format(new Date(e.created_at))),node('strong','وەرگیراو: '+S.format(e.amount)+' دینار'),node('p','قەرزی پێش وەرگرتنەوە: '+S.format(e.balance_before)+' دینار'),node('p','قەرزی دوای وەرگرتنەوە: '+S.format(e.balance_after)+' دینار'),node('p','ئەم باڵانسە هی کاتی تۆمارکردنە؛ قەرزی ئێستای کڕیار دەکرێت گۆڕابێت.'),node('p',e.note),node('small','کۆدی کڕیار: '+e.customer_id),node('br'),node('small',e.id));p.hidden=false;controls();}
async function show(id,print=false){if(busy||!active())return;clearReceipt();const mine=++receiptRequest,epoch=life;try{const s=await KashierData.getCashierRepayment(owner,id);if(mine!==receiptRequest||epoch!==life||!active())return;M.receipt(s,owner,actor,id,pending?.payload.p_id===id?pending.payload:null);if(pending?.payload.p_id===id){removePending();clearBalance();}render(s);if(print)window.print();}catch(e){if(mine===receiptRequest&&epoch===life){denied(e);status((globalThis.KashierLocale?.message(e.message)??e.message));}}}
async function send(){if(!pending||busy||!active())return;const item=pending,epoch=life;busy=true;controls();status('تۆمارکردنی وەرگرتنەوە…');try{const s=await KashierData.postCashierRepayment(item.payload);if(epoch!==life||!active())return;M.receipt(s,owner,actor,item.payload.p_id,item.payload);removePending();clearBalance();$('#repay-amount').value=$('#repay-note').value='';render(s);status(blocked?'تۆمار کرا؛ پاککردنەوەی داواکاری سەرکەوتوو نەبوو، پێش داواکاریی نوێ لەگەڵ خاوەن بیپشکنە.':'وەرگرتنەوە تۆمار کرا؛ D-'+s.entry.movement_no);await recent();}catch(e){if(epoch!==life||!active())return;if(['staff_balance_changed','staff_repay_denied','debt_customer_unavailable','debt_overpayment','debt_invalid_amount','debt_note_required','staff_invalid_request','cash_balance_limit'].includes(e.saleCode)){removePending();clearBalance();status((globalThis.KashierLocale?.message(e.message)??e.message)+' باڵانسی کڕیار دووبارە بپشکنەوە.');}else{denied(e);status('دۆخی داواکاری نادیارە؛ هەمان داواکاری بپشکنەوە. '+(globalThis.KashierLocale?.message(e.message)??e.message));}}finally{busy=false;controls();}}
$('#repay-form').addEventListener('submit',e=>{e.preventDefault();if(busy||pending||blocked||!current||!active()||!$('#repay-form').reportValidity())return;try{const p={p_owner:owner,p_id:crypto.randomUUID(),p_customer:current.customer.id,p_amount:String(S.money($('#repay-amount').value)),p_note:$('#repay-note').value.trim(),p_expected_balance:current.balance};M.payload(p,owner);const item={version:1,actor,owner,payload:p};sessionStorage.setItem(key,JSON.stringify(item));pending=item;clearReceipt();searchRequest++;balanceRequest++;send();}catch(e){status((globalThis.KashierLocale?.message(e.message)??e.message)||'داواکاری نەپارێزرا؛ وەرگرتنەوە نەنێردرا.');}});
$('#repay-search').addEventListener('click',()=>{offset=0;search();});$('#repay-query').addEventListener('input',()=>{searchRequest++;clearBalance();$('#repay-customers').replaceChildren();$('#repay-customer').value='';});$('#repay-previous').addEventListener('click',()=>{offset=Math.max(0,offset-50);search();});$('#repay-next').addEventListener('click',()=>{offset+=50;search();});$('#repay-refresh').addEventListener('click',()=>{if($('#repay-customer').value)select($('#repay-customer').value);else search();});$('#repay-new').addEventListener('click',()=>{if(busy||pending||blocked)return;clearReceipt();clearBalance();$('#repay-amount').value=$('#repay-note').value='';search();});$('#repay-retry').addEventListener('click',send);$('#repay-print').addEventListener('click',()=>{if(selectedReceipt&&active())show(selectedReceipt.entry.id,true);});
try{const item=JSON.parse(sessionStorage.getItem(key)||'null');if(item){if(item.version!==1||item.actor!==actor||item.owner!==owner)throw Error();M.payload(item.payload,owner);pending=item;$('#repay-amount').value=item.payload.p_amount;$('#repay-note').value=item.payload.p_note;status('داواکارییەک ماوە؛ هەمان داواکاری بپشکنەوە.');}}catch{blocked=true;status('داواکاریی پارێزراو نەخوێندرایەوە؛ لەگەڵ خاوەن بیپشکنە.');}
window.addEventListener('pagehide',clearPrivate);window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});window.addEventListener('beforeprint',()=>{if(!active())clearPrivate();});controls();if(!active()){location.replace('auth.html?next='+encodeURIComponent('repayment.html?owner='+owner));}else if(S.uuid(owner)){recent();if(!pending&&!blocked)search();}else status('ناسنامەی دوکان نادروستە.');
})();
